package test;
import org.eclipse.jface.viewers.Viewer;
import org.eclipse.jface.viewers.ViewerFilter;
public class MyFilter extends ViewerFilter {
    private ViewerFilter fDelegateFilter; // Can be null based on context in original diff

    public MyFilter(ViewerFilter delegateFilter) {
        this.fDelegateFilter = delegateFilter;
    }

    @Override
    public boolean select(Viewer viewer, Object parent, Object element) {
        // Potential NPE if fDelegateFilter is null
        return fDelegateFilter.select(viewer, parent, element);
    }
}

afterExample:
package test;
import org.eclipse.jface.viewers.Viewer;
import org.eclipse.jface.viewers.ViewerFilter;
public class MyFilter extends ViewerFilter {
    private ViewerFilter fDelegateFilter;

    public MyFilter(ViewerFilter delegateFilter) {
        this.fDelegateFilter = delegateFilter;
    }

    @Override
    public boolean select(Viewer viewer, Object parent, Object element) {
        return fDelegateFilter != null ? fDelegateFilter.select(viewer, parent, element) : true;
    }
}

