package test;
import org.eclipse.jface.viewers.Viewer;
import org.eclipse.jface.viewers.ViewerFilter;
class AnotherFilter extends ViewerFilter {
    private ViewerFilter anotherFilter;

    public AnotherFilter(ViewerFilter filter) {
        this.anotherFilter = filter;
    }

    @Override
    public boolean select(Viewer viewer, Object parent, Object element) {
        return anotherFilter.equals(viewer); // Different method call, should not match
    }
}
public class NotMatchingClass {
    void someMethod(Object obj) {
        String s = "hello";
        s.length(); // Not a ViewerFilter
    }
}
